//! Builds the Omega token check (`om/tkcheck.om`, bound by omega-bridge in
//! `om/gen`, regenerated by `om/regen.sh`) into a static library, with the
//! flags omega-bridge's `tools/native` qualifies it with. The embedded code is
//! AArch64; on any other target nothing is built and `bearer` refuses an
//! existing token file instead.

fn main() {
    println!("cargo::rustc-check-cfg=cfg(oh_tkcheck)");
    for f in ["om/gen/omega_native.c", "om/gen/omega_native.h", "om/gen/omega_native.rs"] {
        println!("cargo::rerun-if-changed={f}");
    }
    let os = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let arch = std::env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
    if os != "linux" || arch != "aarch64" {
        return;
    }
    let dir = std::path::PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap()).join("om/gen");
    cc::Build::new()
        .file(dir.join("omega_native.c"))
        .std("gnu11")
        .opt_level(2)
        .warnings(true)
        .extra_warnings(true)
        .warnings_into_errors(true)
        .flag("-include")
        .flag(dir.join("omega_native.h").to_str().unwrap())
        .flag("-mbranch-protection=standard")
        // The binding's `#[link(name = "omega_native")]` names this archive.
        .compile("omega_native");
    println!("cargo::rustc-cfg=oh_tkcheck");
}
